"""Writes _bmad-output/poc/character-clip-manifest.md from the measure/author reports (run by build_character_assets.ps1).

python make_manifest.py <reports dir> <out.md>
"""
import json
import os
import sys

PACK_USED = ["Idle", "Idle_Neutral", "Walk", "Run", "Run_Back", "Run_Left", "Run_Right", "Interact"]
AUTHORED_ORDER = [
    "Jog", "JogBack", "JogLeft", "JogRight", "Sprint", "SprintBack", "SprintLeft", "SprintRight",
    "CrouchWalk", "CrouchWalkBack", "CrouchWalkLeft", "CrouchWalkRight", "Crouch_Idle",
    "Squat_Enter", "Squat_Hold", "Squat_Exit", "Sit_Enter", "Sit_Loop", "Sit_Exit",
    "Sleep_Down", "Sleep_Loop", "Sleep_Wake", "Jump_Start", "Jump_Air", "Jump_Land",
    "Jog_Full", "JogBack_Full", "JogLeft_Full", "JogRight_Full", "Sprint_Full", "SprintBack_Full", "SprintLeft_Full", "SprintRight_Full",
    "Crouch_Idle_Low", "Crouch_Idle_High", "Squat_Hold_Low", "Squat_Hold_High", "Sit_Loop_Low", "Sit_Loop_High", "Sleep_Loop_High",
    "Squat_Enter_Low", "Squat_Enter_High", "Squat_Exit_Low", "Squat_Exit_High", "Sit_Enter_Low", "Sit_Enter_High", "Sit_Exit_Low", "Sit_Exit_High",
    "Sleep_Down_High", "Sleep_Wake_High",
    "CrouchWalk_Low", "CrouchWalk_High", "CrouchWalkBack_Low", "CrouchWalkBack_High",
    "CrouchWalkLeft_Low", "CrouchWalkLeft_High", "CrouchWalkRight_Low", "CrouchWalkRight_High",
]
STANCE = {  # stance each clip belongs to, for the table
    "Idle": "Stand", "Idle_Neutral": "Stand", "Walk": "Stand", "Run": "Stand", "Run_Back": "Stand",
    "Run_Left": "Stand", "Run_Right": "Stand", "Interact": "Stand",
}
GAME_SPEEDS = {"Walk": (1.15, 1.5), "Run": (3.0,), "Jog": (5.0,), "Sprint": (8.0,), "CrouchWalk": (1.25, 1.75, 2.5)}


def load(path):
    with open(path) as f:
        return json.load(f)


def rates(base, speed):
    for key, speeds in GAME_SPEEDS.items():
        if base.startswith(key) and not (key == "Run" and base.startswith("Run_") and False):
            return ", ".join(f"{v:g} m/s: {v / speed:.2f}" for v in speeds)
    return ""


def main():
    rep, out = sys.argv[1], sys.argv[2]
    lines = [
        "# Character clip manifest",
        "",
        "Generated by `tools/blender/character/make_manifest.py` (run by `build_character_assets.ps1`). Do not edit by hand.",
        "Measured values are read back from the FBX files themselves (Blender re-import, 30 fps), not from the authoring script.",
        "",
        "## Sources and licenses",
        "",
        "| Source | License | Record |",
        "|---|---|---|",
        "| Pack clips (`Animations.fbx`, Quaternius Ultimate Modular Men, Feb 2022, zip `Ultimate Modular Men- Feb 2022-20261005T045546Z-1-001.zip`) | CC0 1.0 | `Assets/ThirdParty/Quaternius/ModularCharacters/Men/License.txt` |",
        "| Pack clips (`Animations.fbx`, Quaternius Ultimate Modular Women, Apr 2022, zip `Ultimate Modular Women - April 2022-20261005T045539Z-1-001.zip`) | CC0 1.0 | `Assets/ThirdParty/Quaternius/ModularCharacters/Women/License.txt` |",
        "| Authored clips (`tools/blender/character/author_clips.py`, one FBX per gender) | project-authored; no third-party material | this file |",
        "",
        "Column key: speed = ground speed the clip's planted foot moves at (clip's own stride x cycles/s); rate = game speed / clip speed",
        "(designer-2 limit 1.4 at 5, 8 m/s and 0.70-1.40 over the crouch range 1.25-2.50); drift = largest world displacement of a planted foot",
        "(foot within 3 cm of its lowest height) when the body moves at the clip's own speed (spec H4 limit 0.10 m); eye = hidden-head eye point",
        "(the eye point measured from the Head part mesh, see Eye point below; metres above the floor, feet at 0 - the body drop below the player origin is not included).",
        "",
    ]
    lines += ["## Eye point", "",
              "Method (`tools/blender/character/measure_head_eye.py`): the mean of the vertices of the head mesh's eye material (men: `Eye`; women: the",
              "smallest material furthest forward, `Brown`), at rest, expressed from the Head bone head. Authored clips and the tables below use it.", "",
              "| Head part | Up m | Forward m | Method |", "|---|---|---|---|"]
    for gender in ("Men", "Women"):
        for head, v in load(os.path.join(rep, f"eye-point-{gender}.json")).items():
            lines.append(f"| {gender} {head} | {v.get('up_m', '-')} | {v.get('forward_m', '-')} | {v.get('method', v.get('error'))} |")
    lines += ["", "All five men's heads give the same point (the head mesh is shared), so Farmer, the default look, represents them. The earlier guess",
              "(0.103 up, 0.08 forward) is replaced by this point.", ""]
    hand_lines = []
    for gender in ("Men", "Women"):
        pack = load(os.path.join(rep, f"measured-pack-{gender}.json"))["clips"]
        auth = load(os.path.join(rep, f"measured-authored-{gender}.json"))["clips"]
        if gender == "Men":
            pd = {n: (pack.get(f"CharacterArmature|{n}") or pack.get(n) or {}).get("plant_drift_m_max") for n in ("Walk", "Run", "Run_Back")}
        authored = load(os.path.join(rep, f"authored-{gender}.json"))
        info = authored["clips"]
        scale = authored.get("skeleton_scale", 1.0)
        lines += [f"## {gender}", "", f"Skeleton scale on the body: {scale} (uniform; speed, drift and eye below are on the scaled body, clips are authored unscaled).", "", "| Clip | Source | License | Frames (key rate: pack 30, authored 60) | Duration s | Loop | Speed m/s | Playback rate | Drift m | Eye z min / max |",
                  "|---|---|---|---|---|---|---|---|---|---|"]
        for name in PACK_USED:
            c = pack.get(f"CharacterArmature|{name}") or pack.get(name)
            if not c:
                continue
            sp = round(c["clip_speed_mps"] * scale, 3) if c["clip_speed_mps"] else None
            lines.append(f"| {name} | pack | CC0 1.0 | {c['frames']} | {c['duration_s']} | {'yes' if name != 'Interact' else 'no'} | "
                         f"{sp if sp else '-'} | {rates(name, sp) if sp else ''} | {round(c['plant_drift_m_max'] * scale, 3) if sp else '-'} | {round(c['eye_z_min'] * scale, 3)} / {round(c['eye_z_max'] * scale, 3)} |")
        for name in AUTHORED_ORDER:
            c = auth.get(name)
            if not c:
                continue
            loco = name.startswith(("Jog", "Sprint", "CrouchWalk"))
            sp = round(c["clip_speed_mps"] * scale, 3) if loco else None
            lines.append(f"| {name} | {'authored, IN USE by the shadow body (full swing, via the shadow override)' if name.endswith('_Full') else 'authored, IN USE by the view body (capped arms, base controller)' if name.startswith(('Jog', 'Sprint')) else 'authored'} | project | {c['frames']} | {c['duration_s']} | {'yes' if info[name]['loop'] else 'no'} | "
                         f"{sp if sp else '-'} | {rates(name, sp) if sp else ''} | {round(c['plant_drift_m_max'] * scale, 3) if sp else '-'} | {round(c['eye_z_min'] * scale, 3)} / {round(c['eye_z_max'] * scale, 3)} |")
        hv = {k: v["hand_in_view"] for k, v in auth.items() if v.get("hand_in_view") and not k.endswith("_Full")}
        if hv:
            worst = max(max(h["frames_with_a_hand_in_view"].values()) for h in hv.values())
            samples = {k: h["samples"] for k, h in hv.items()}
            hand_lines.append(f"- {gender}: Jog and Sprint (all directions): most samples with a wrist or fingertip inside the first-person frustum at any pitch -15 to +30 = {worst} of {min(samples.values())}+ (camera fixed at the stand eye, FOV 70 vertical, 16:9, near 0.1, body back offset not counted).")
        speeds = [{"name": k.split("|")[-1], "speed": round(v["clip_speed_mps"] * scale, 4)} for k, v in {**pack, **auth}.items()
                  if v.get("clip_speed_mps") and k.split("|")[-1].startswith(("Walk", "Run", "Jog", "Sprint", "CrouchWalk"))]
        with open(os.path.join(rep, f"speeds-{gender}.json"), "w") as f:
            json.dump({"scale": scale, "clips": speeds}, f, indent=1)
        unused = sorted(k.split('|')[-1] for k in pack if k.split('|')[-1] not in PACK_USED)
        lines += ["", f"Pack clips imported but not used by the stance set (CC0): {', '.join(unused)}.", ""]
    lines += [
        "## Limits named here",
        "",
        "- Walk-speed strafe and walk-back clips do not exist (the pack has Run_Left/Run_Right/Run_Back only, about 3.0 m/s). Below that speed strafing and",
        "  backing play the Run_* clips at a reduced rate; foot slide there is not covered by the 0.10 m check. Future issue 14 (td).",
        "- Strafe and back clip speeds equal the forward node speeds in every family (Run 3.03 / Run_Back 3.03 / Run_Left 3.03 / Run_Right 3.03; Jog, Sprint and CrouchWalk identical in all four directions), so CharacterClipSet.LocomotionRate holds while strafing.",
        "- Locomotion blend (td): Walk (stand forward) and CrouchWalk play alone from 0.7 to 1.4 x their on-body speed (rate edge exactly 0.70; crouch 1.25 to 2.5 m/s is rate 0.70 to 1.40) and blend toward Idle only below the 0.70 edge. Strafe and back play Run_* alone from 0.7 to 1.0 x their speed. Jog and Sprint play alone at 5 and 8 m/s.",
        "- Foot plant: authored locomotion clips are keyed at 60 fps; the first and last swing sample of each step keeps moving back with the ground while already clear of the 3 cm plant band, so the in-band foot does not slide. The drift column is the largest horizontal distance between any two samples of a plant, sampled 4x between keys, body travel at the clip's own speed removed.",
        "- Sprint re-authored (director amend8): cycle 0.667 s (3.0 steps per second at rate 1, 4.1 at the 1.379 rate), stance about 0.11 s per foot, flight about 0.22 s per step (65 percent of the cycle neither foot planted; the hip peaks in flight); mid-stance hip 0.812 m, stance knee 48 degrees, swing knee peak 113 degrees, torso pitch 10.4 degrees forward (men, unscaled; pack Run 0.812 m, 48, 127 peak, 5.4); step 1.88 m (1.94 on the body). The stance foot moves at 5.80 m/s ON THE BODY for both body types (authored at 5.80 / scale), so the playback rate is 1.379 at 8 m/s, reached by the flight, not by deeper knees. Full arms (director amend8e, pass 2, left and right identical, in opposition to the legs): the shoulder swings from 44 degrees forward to 81 degrees back (world frame; amplitude 125; pack Run 105 on one arm and 55 on the other; the earlier set 144 with the elbow held at 113 and 130), the elbow flexion varies 82 to 99 degrees with the swing; the wrist runs from 0.11 m behind the shoulder to 0.27 m in front of it (torso frame) and reaches 0.07 m above the shoulder (world frame; 0.115 in the torso frame) on the forward swing, the chin-height ceiling of about 0.10 m the director set. A stricter pass 3 (the wrist always 0.16 to 0.31 m below the shoulder, elbow 81, amplitude 89) is kept in the authoring script (SPRINT_FULL_ARMS_V3), unused; the fingers keep the pack's pose (spread 37 degrees, same as the pack Run; relaxed hands deferred to future issue 35). Known limits: SprintBack (men) overreaches its leg by 1.0 cm at one phase; the women's Sprint torso pitch and hip height differ (their rig).",
        "- Capped arms (the view body's clips): the jog and sprint arm swing is narrowed (forward swing scaled down, elbows tucked, hands lower and slightly outward) so no hand enters the first-person view; one pose is shared by the shadow and view bodies. Measured by measure_clips.py hand_view:",
        *hand_lines,
        "- Arm cap (director amend7, td's two-Animator method): the SHADOW body's Animator plays the full-swing clips (names ending _Full: Jog, Sprint and their Back, Left, Right; Jog swing 35 / elbow 85, Sprint 55 / 95) through CharacterAnimator_<type>_Shadow.overrideController, which maps exactly the 8 capped clips to their _Full versions. The first-person VIEW body has its own Animator on the base controller (capped arms: Jog swing 28 / forward scale 0.25 / elbow 30 / 14 degrees out, Sprint 50 / 0.15 / 35 / 16). The driver writes the same parameters to both Animators, so the 2D blend trees give the same weights; every bone outside the arm chains (Shoulder.L/R and below) is copied from the shadow each LateUpdate; a sync guard resyncs the view Animator on state or normalized-time drift above 0.01 and counts it (CharacterViewCopy.Resyncs). Legs, root, spine, speeds, stride and plant are identical in each capped / _Full pair (asserted to 1e-4 on every non-arm curve). Hands in the first-person frustum at pitch -15 to +30 (capped clips): 0 samples, measured in Blender (below) and asserted in an EditMode test on the view body.",
        f"- Known pack limits (future issue 14, td): the pack clips cannot be edited by script. Their plant drift by the same measure as every figure here (largest horizontal distance between any two samples of a plant, band 3 cm, 4x key rate, unscaled): Walk {pd['Walk']} m (tower speeds 1.15 / 1.5), Run {pd['Run']} m, Run_Back {pd['Run_Back']} m. H4 is graded forward at Jog 5 and Sprint 8 m/s only (the authored clips measure 0.000 m).",
        "- Strafing and backing slower than 0.7 x the Run_* speed (about 2.1 m/s, which includes the tower speeds) blends with Idle and slides; the pack has no walk-speed strafe or back clips. Known limit, future issue 14.",
        "- Speeds in this file and Speed(name) in CharacterClipSet are ON THE BODY (authored speed x skeleton scale); LocomotionRate multiplies its unscaled node speeds by the scale argument once.",
        "- Authored clips are script-built placeholders: planted feet are exact, the upper body is simple (spine lean, arm swing, no hands or head turn).",
        "- Women's rig: the standing eye reachable with the authored leg length is below 1.65 m (see the Women stand eye in the authoring report); all lowered stances hit the designer's eye heights.",
        "- Crouch_Idle, Squat_* and Sit_* poses keep the feet where the standing feet were and move the pelvis behind the eye anchor, so the head stays under the camera.",
        "",
    ]
    with open(out, "w", newline="\n") as f:
        f.write("\n".join(lines))
    print("wrote", out)


main()
